import sys

def find(parent, i):
    if parent[i] != i:
        parent[i] = find(parent, parent[i])
    return parent[i]

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def kruskal_mst(n, edges):
    edges = sorted(edges, key=lambda x: x[2], reverse=True)
    parent = [i for i in range(n)]
    rank = [0] * n
    mst_edges = []

    while edges:
        u, v, w = edges.pop()
        x = find(parent, u)
        y = find(parent, v)

        if x != y:
            mst_edges.append((u, v, w))
            union(parent, rank, x, y)

    return mst_edges

def main():
